package com.bct.ngtpa.apiservice.application.dto.session.authenticated;public record ProtectedAuthenticatedSession(String version,String ciphertext,String nonce,String authenticationTag){public ProtectedAuthenticatedSession{version=required(version,"version");ciphertext=required(ciphertext,"ciphertext");nonce=required(nonce,"nonce");authenticationTag=required(authenticationTag,"authenticationTag");}private static String required(String v,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" must not be blank");return v.trim();}@Override public String toString(){return "ProtectedAuthenticatedSession[version="+version+", ciphertext=<redacted>, nonce=<redacted>, authenticationTag=<redacted>]";}}
